const body = $json.body || $json;

const question =
  body.message ||
  body.question ||
  body.chatInput ||
  body.prompt ||
  "";

const sessionId = body.sessionId || "default-session";

if (!question || !question.trim()) {
  return [
    {
      json: {
        error: true,
        question: "",
        sessionId,
        answer: "Please provide a question.",
        specialistResults: [],
        evidenceGraph: {
          nodes: [],
          edges: [],
        },
      },
    },
  ];
}

const ragLimit = body.ragLimit !== undefined ? Number(body.ragLimit) : 3;
const reasoning = body.reasoning || "low";

return [
  {
    json: {
      error: false,
      question: question.trim(),
      sessionId,
      ragLimit,
      reasoning,
      timestamp: new Date().toISOString(),
    },
  },
];

let incoming = $json || {};

let question =
  incoming.question ||
  incoming.message ||
  incoming.chatInput ||
  incoming.prompt ||
  incoming.body?.question ||
  incoming.body?.message ||
  incoming.body?.chatInput ||
  incoming.body?.prompt ||
  "";

// fallback: read directly from Normalize Chat Input node
try {
  const normalized = $("Normalize Chat Input").first().json;
  question =
    question ||
    normalized.question ||
    normalized.message ||
    normalized.body?.question ||
    normalized.body?.message ||
    "";
} catch (e) {
  // ignore
}

question = String(question || "").trim();
const q = question.toLowerCase();

const selectedAgents = [];

const isChargingStationQuestion =
  q.includes("charging station") ||
  q.includes("charging stations") ||
  q.includes("station") ||
  q.includes("stations") ||
  q.includes("located") ||
  q.includes("location") ||
  q.includes("site") ||
  q.includes("sites") ||
  q.includes("country") ||
  q.includes("countries");

const isProcurementQuestion =
  q.includes("purchase") ||
  q.includes("purchasing") ||
  q.includes("purchase order") ||
  q.includes("purchase orders") ||
  q.includes("po-") ||
  /\bpo\b/.test(q) ||
  q.includes("order") ||
  q.includes("orders") ||
  q.includes("supplier") ||
  q.includes("vendor") ||
  q.includes("material") ||
  q.includes("inventory") ||
  q.includes("stock") ||
  q.includes("closed") ||
  q.includes("open") ||
  q.includes("status");

const isRiskQuestion =
  q.includes("risk") ||
  q.includes("risky") ||
  q.includes("delay") ||
  q.includes("delayed") ||
  q.includes("bottleneck") ||
  q.includes("critical") ||
  q.includes("failure") ||
  q.includes("incident") ||
  q.includes("disruption");

const isQualityQuestion =
  q.includes("quality") ||
  q.includes("test") ||
  q.includes("testing") ||
  q.includes("defect") ||
  q.includes("inspection") ||
  q.includes("audit") ||
  q.includes("notification");

const isSustainabilityQuestion =
  q.includes("carbon") ||
  q.includes("emission") ||
  q.includes("emissions") ||
  q.includes("co2") ||
  q.includes("energy") ||
  q.includes("recycling") ||
  q.includes("recovery") ||
  q.includes("waste") ||
  q.includes("sustainability") ||
  q.includes("environment");

if (isChargingStationQuestion) {
  selectedAgents.push("logistics_specialist");
}

if (isProcurementQuestion) {
  selectedAgents.push("procurement_specialist");
}

if (isRiskQuestion) {
  selectedAgents.push("risk_analyst");
}

if (isQualityQuestion) {
  selectedAgents.push("quality_analyst");
}

if (isSustainabilityQuestion) {
  selectedAgents.push("sustainability_analyst");
}

return [
  {
    json: {
      ...incoming,
      question,
      selectedAgents,
      runProcurement: selectedAgents.includes("procurement_specialist"),
      runRisk: selectedAgents.includes("risk_analyst"),
      runLogistics: selectedAgents.includes("logistics_specialist"),
      runSustainability: selectedAgents.includes("sustainability_analyst"),
      runQuality: selectedAgents.includes("quality_analyst"),
      routingDebug: {
        inputKeys: Object.keys(incoming),
        rawInput: incoming,
        questionSeenByRouter: question,
        normalizedQuestion: q,
        selectedAgents,
        isChargingStationQuestion,
        isProcurementQuestion,
        isRiskQuestion,
        isQualityQuestion,
        isSustainabilityQuestion,
      },
    },
  },
];

const question = $("Normalize Chat Input").first().json.question || "";
const sessionId = $("Normalize Chat Input").first().json.sessionId || "default-session";
const selectedAgents = $("Route Question").first().json.selectedAgents || [];
const sourceChunks = $("Parse RAG Chunks").first().json.sourceChunks || [];

function getNodeJson(nodeName) {
  try {
    return $(nodeName).first().json;
  } catch (e) {
    return {
      agent: nodeName,
      status: "error",
      answer: `Could not read output from ${nodeName}`,
      keyFindings: [],
      recommendations: [],
      confidence: "low",
      error: e.message,
    };
  }
}

const procurement = getNodeJson("Run Procurement Specialist");
const risk = getNodeJson("Run Risk Analyst");
const logistics = getNodeJson("Run Logistics Specialist");
const sustainability = getNodeJson("Run Sustainability Analyst");
const quality = getNodeJson("Run Quality Analyst");

const allSpecialistResults = [
  procurement,
  risk,
  logistics,
  sustainability,
  quality,
].filter(Boolean);

const specialistResults = allSpecialistResults.filter(
  (result) => result.status !== "skipped"
);

const toolsUsed = [];
if (sourceChunks.length > 0) {
  toolsUsed.push({
    id: "vector_search",
    name: "Vector Search (Unstructured RAG)",
    status: "success",
    inputSummary: question,
    outputSummary: `Found ${sourceChunks.length} matching unstructured documents.`
  });
}

const cypherQueries = [];

specialistResults.forEach((spec) => {
  if (spec.generatedCypher) {
    cypherQueries.push({
      agent: spec.agent || "unknown_agent",
      query: spec.generatedCypher,
    });
  }
});

const allRecords = [];
specialistResults.forEach((spec) => {
  if (spec.evidence && typeof spec.evidence === "object") {
    Object.values(spec.evidence).forEach((val) => {
      if (Array.isArray(val)) {
        allRecords.push(...val);
      }
    });
  }
});

let tableColumns = [];
let tableRows = [];
if (allRecords.length > 0) {
  const cols = new Set();
  allRecords.forEach((row) => {
    Object.keys(row).forEach((k) => cols.add(k));
  });
  tableColumns = Array.from(cols);
  tableRows = allRecords;
}

return [
  {
    json: {
      question,
      sessionId,
      selectedAgents,
      routingDebug: $("Route Question").first().json.routingDebug || {},
      specialistResults,
      allSpecialistResults,
      sourceChunks,
      toolsUsed,
      cypherQueries,
      tableColumns,
      tableRows,
      embeddingMode: $("GetEmbeddingAPI").first().json.embeddingMode || "fallback",
      timestamp: new Date().toISOString(),
    },
  },
];

const embedding = $json.embedding;
const embeddingMode = $json.embeddingMode || "fallback";

let ragLimit = 3;
try {
  ragLimit = $("Normalize Chat Input").first().json.ragLimit || 3;
} catch (e) {
  // ignore
}

const chunkQuery = `
  CALL db.index.vector.queryNodes('chunk_embeddings', $limit, $embedding)
  YIELD node, score
  RETURN node.file_name AS filename, node.index AS chunk_index, node.text AS content, score
`;

return [{
  json: {
    body: {
      query: chunkQuery,
      params: {
        embedding,
        limit: ragLimit
      }
    },
    embeddingMode
  }
}];

const results = $json.results || [];
const sourceChunks = results.map((r, idx) => ({
  id: `chunk_${idx}`,
  documentName: r.filename || "Unknown Document",
  text: r.content || ""
}));

let original = {};
try {
  original = $("Normalize Chat Input").first().json;
} catch (e) {
  original = {};
}

return [{
  json: {
    ...original,
    sourceChunks
  }
}];

