={{ {
  query: `
MATCH (n)
WITH labels(n)[0] AS label, keys(n) AS keys
UNWIND keys AS property
RETURN
  label,
  collect(DISTINCT property)[0..30] AS properties,
  count(*) AS sample_count
ORDER BY label
`,
  params: {}
} }}
